scripts.onUpdate:
function getTilemap(entity) {
  const direct = entity && entity.getComponent && entity.getComponent("Tilemap2DComponent");
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === "Tilemap2DComponent" || String(item.UniqueSymbol) === "Symbol(Tilemap2DComponent)")) return item;
  }
  return null;
}

const config = api.read.data() || {};
const boardEntity = api.read && api.read.find("2048 Board");
const board = getTilemap(boardEntity);
const scoreHud = getTilemap(api.read && api.read.find("2048 Score"));
const bestHud = getTilemap(api.read && api.read.find("2048 Best"));
const statusHud = getTilemap(api.read && api.read.find("2048 Status"));
const tileTextEntities = [];
const tileVisualEntities = [];
for (let i = 0; i < 16; i++) {
  tileTextEntities.push(api.read && api.read.find("2048 Tile " + i));
  tileVisualEntities.push(api.read && api.read.find("2048 Tile Visual " + i));
}
const scoreTextEntity = api.read && api.read.find("2048 Score Text");
const bestTextEntity = api.read && api.read.find("2048 Best Text");
const statusTextEntity = api.read && api.read.find("2048 Status Text");

function getCanvasText(entity) {
  const direct = entity && entity.getComponent && entity.getComponent("CanvasTextComponent");
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === "CanvasTextComponent" || String(item.UniqueSymbol) === "Symbol(CanvasTextComponent)")) return item;
  }
  return null;
}

function setStableText(entity, key, value) {
  if (!entity) return;
  entity.disabled = !value;
  const text = getCanvasText(entity);
  if (text) text.text = String(value || "");
  else api.scene && api.scene.setText(key, String(value || ""));
}

if (!board) {
  api.debug.console.warn("2048 Starter Kit requires 2048 Board with Tilemap2DComponent.");
  return;
}

const state = component.state || (component.state = {});
const rows = Number(config.rows || 4);
const cols = Number(config.columns || 4);
const target = Number(config.target || 2048);
const emptyIndex = Number(config.emptyPaletteIndex || 1);
const valuePalette = config.valuePalette || {
  2: 2,
  4: 3,
  8: 4,
  16: 5,
  32: 6,
  64: 7,
  128: 8,
  256: 9,
  512: 10,
  1024: 11,
  2048: 12,
  4096: 13,
  8192: 14
};
const digits = {
  0: ["111", "101", "101", "101", "111"],
  1: ["010", "110", "010", "010", "111"],
  2: ["111", "001", "111", "100", "111"],
  3: ["111", "001", "111", "001", "111"],
  4: ["101", "101", "111", "001", "001"],
  5: ["111", "100", "111", "001", "111"],
  6: ["111", "100", "111", "101", "111"],
  7: ["111", "001", "001", "001", "001"],
  8: ["111", "101", "111", "101", "111"],
  9: ["111", "101", "111", "001", "111"]
};

function makeGrid() {
  return Array.from({ length: rows }, function () { return Array(cols).fill(0); });
}

function randomSpawnValue() {
  const values = config.spawnValues || [2, 2, 2, 2, 2, 2, 2, 2, 2, 4];
  return Number(values[Math.floor(Math.random() * values.length)] || 2);
}

function emptyCells() {
  const cells = [];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (!state.grid[y][x]) cells.push({ x: x, y: y });
    }
  }
  return cells;
}

function spawnTile() {
  const cells = emptyCells();
  if (!cells.length) return null;
  const cell = cells[Math.floor(Math.random() * cells.length)];
  state.grid[cell.y][cell.x] = randomSpawnValue();
  return cell;
}

function reset() {
  state.grid = makeGrid();
  state.score = 0;
  state.best = Math.max(Number(state.best || 0), Number(config.best || 0));
  state.phase = "playing";
  state.won = false;
  state.movedAt = 0;
  state.transitions = [];
  state.animationToken = (state.animationToken || 0) + 1;
  const startTiles = Math.max(1, Number(config.startTiles || 2));
  for (let i = 0; i < startTiles; i++) {
    const spawned = spawnTile();
    if (spawned) state.transitions.push({ value: state.grid[spawned.y][spawned.x], fromX: spawned.x, fromY: spawned.y, toX: spawned.x, toY: spawned.y, spawn: true });
  }
}

function valuesEqual(a, b) {
  return Number(a || 0) === Number(b || 0);
}

function canMove() {
  if (emptyCells().length) return true;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const value = state.grid[y][x];
      if (x + 1 < cols && valuesEqual(value, state.grid[y][x + 1])) return true;
      if (y + 1 < rows && valuesEqual(value, state.grid[y + 1][x])) return true;
    }
  }
  return false;
}

function lineCoords(direction, index) {
  const result = [];
  if (direction === "left") for (let x = 0; x < cols; x++) result.push({ x: x, y: index });
  if (direction === "right") for (let x = cols - 1; x >= 0; x--) result.push({ x: x, y: index });
  if (direction === "up") for (let y = 0; y < rows; y++) result.push({ x: index, y: y });
  if (direction === "down") for (let y = rows - 1; y >= 0; y--) result.push({ x: index, y: y });
  return result;
}

function slideEntries(entries) {
  const packed = entries.filter(function (entry) { return entry.value; });
  const out = [];
  let gained = 0;
  for (let i = 0; i < packed.length; i++) {
    if (i + 1 < packed.length && packed[i].value === packed[i + 1].value) {
      const merged = packed[i].value * 2;
      out.push({ value: merged, sources: [packed[i], packed[i + 1]] });
      gained += merged;
      i++;
    } else {
      out.push({ value: packed[i].value, sources: [packed[i]] });
    }
  }
  while (out.length < entries.length) out.push({ value: 0, sources: [] });
  return { entries: out, gained: gained };
}

function move(direction) {
  if (state.phase !== "playing") return false;
  let changed = false;
  let gained = 0;
  const transitions = [];
  const count = direction === "left" || direction === "right" ? rows : cols;
  for (let i = 0; i < count; i++) {
    const coords = lineCoords(direction, i);
    const before = coords.map(function (cell) { return { value: state.grid[cell.y][cell.x], x: cell.x, y: cell.y }; });
    const result = slideEntries(before);
    for (let j = 0; j < coords.length; j++) {
      const cell = coords[j];
      const nextValue = result.entries[j].value;
      if (state.grid[cell.y][cell.x] !== nextValue) changed = true;
      state.grid[cell.y][cell.x] = nextValue;
      for (const source of result.entries[j].sources) {
        transitions.push({ value: source.value, fromX: source.x, fromY: source.y, toX: cell.x, toY: cell.y, mergedTo: nextValue });
      }
    }
    gained += result.gained;
  }
  if (!changed) return false;
  state.score += gained;
  state.best = Math.max(state.best, state.score);
  state.movedAt = (state.movedAt || 0) + 1;
  if (state.grid.some(function (row) { return row.some(function (value) { return value >= target; }); })) {
    state.phase = "won";
    state.won = true;
  }
  const spawned = spawnTile();
  if (spawned) transitions.push({ value: state.grid[spawned.y][spawned.x], fromX: spawned.x, fromY: spawned.y, toX: spawned.x, toY: spawned.y, spawn: true });
  state.transitions = transitions;
  state.animationToken = (state.animationToken || 0) + 1;
  if (!canMove()) state.phase = "lost";
  return true;
}

function setTilemapTransform(entity, x, y) {
  const transform = entity && entity.getComponent && entity.getComponent("Transform2D");
  if (!transform) return;
  transform.x = x;
  transform.y = y;
}

function setTextBox(entity, x, y, width, height, fontSize, color) {
  const transform = entity && entity.getComponent && entity.getComponent("Transform2D");
  if (transform) {
    transform.x = x;
    transform.y = y;
  }
  const text = getCanvasText(entity);
  if (!text) return;
  const style = text.style || {};
  const next = {
    ...style,
    width: Math.max(1, Math.floor(width)),
    height: Math.max(1, Math.floor(height)),
    resolutionScale: Number(config.textResolutionScale || 2),
    backgroundColor: "rgba(255,255,255,0)",
    borderWidth: 0,
    padding: 0,
    textAlign: "center",
    verticalAlign: "middle",
    fontSize: Math.max(8, Math.floor(fontSize)),
    fontFamily: "system-ui, sans-serif",
    fontWeight: "800",
    lineHeight: 1,
    whiteSpace: "pre-line",
    color: color || "#f9f6f2"
  };
  if (
    style.width !== next.width ||
    style.height !== next.height ||
    style.fontSize !== next.fontSize ||
    style.color !== next.color ||
    style.resolutionScale !== next.resolutionScale
  ) {
    text.style = next;
  }
}

function layoutTilemap(tilemap, cellWidth, cellHeight, gap) {
  if (!tilemap) return;
  tilemap.cellWidth = cellWidth;
  tilemap.cellHeight = cellHeight;
  tilemap.gap = gap;
}

function getPosition(entity) {
  const transform = entity && entity.getComponent && entity.getComponent("Transform2D");
  return transform ? { x: transform.x, y: transform.y } : { x: 0, y: 0 };
}

function cellPosition(column, row) {
  const layout = state.layout || { boardX: 0, boardY: 0, cell: 64, tileInset: 4, rows: rows };
  return {
    x: layout.boardX + column * layout.cell + layout.tileInset,
    y: layout.boardY + (layout.rows - 1 - row) * layout.cell + layout.tileInset,
  };
}

function setVisualTile(slot, value, x, y, size) {
  const entity = tileVisualEntities[slot];
  const tilemap = getTilemap(entity);
  if (!tilemap) return;
  layoutTilemap(tilemap, size, size, 0);
  tilemap.setCell(0, 0, value ? Number(valuePalette[value] || valuePalette[target] || 12) : 0);
  setTilemapTransform(entity, x, y);
}

function addTween(entity, from, to, duration, scaleFrom, scaleTo) {
  if (!entity || !api.read.components || !api.read.components.Tween2DComponent) return;
  const tweenTo = { x: to.x, y: to.y };
  const tweenFrom = { x: from.x, y: from.y };
  if (scaleFrom !== undefined || scaleTo !== undefined) {
    tweenFrom.scaleX = scaleFrom ?? 1;
    tweenFrom.scaleY = scaleFrom ?? 1;
    tweenTo.scaleX = scaleTo ?? 1;
    tweenTo.scaleY = scaleTo ?? 1;
  }
  entity.addComponent(new api.read.components.Tween2DComponent({
    from: tweenFrom,
    to: tweenTo,
    duration: duration,
    easing: config.tileMoveEasing || "cubicOut",
    removeOnComplete: true,
  }));
}

function updateLayout() {
  const canvas = document.getElementById("player-canvas");
  const width = Math.max(1, canvas && canvas.clientWidth || window.innerWidth || 390);
  const height = Math.max(1, canvas && canvas.clientHeight || window.innerHeight || 844);
  const portrait = height >= width;
  const margin = portrait ? 18 : 30;
  const availableWidth = portrait ? width - margin * 2 : Math.min(width * 0.55, width - 320);
  const availableHeight = portrait ? height - 220 : height - margin * 2;
  const cell = Math.max(44, Math.floor(Math.min(availableWidth / cols, availableHeight / rows, portrait ? 86 : 108)));
  const gap = Math.max(3, Math.floor(cell * 0.07));
  const boardWidth = cols * cell;
  const boardHeight = rows * cell;
  const boardX = portrait ? -boardWidth / 2 : -boardWidth / 2 - Math.min(140, width * 0.12);
  const boardY = portrait ? -boardHeight / 2 - 8 : -boardHeight / 2;
  layoutTilemap(board, cell, cell, gap);
  setTilemapTransform(boardEntity, boardX, boardY);

  const digitCell = Math.max(6, Math.floor(cell * (portrait ? 0.18 : 0.16)));
  if (scoreHud) {
    layoutTilemap(scoreHud, digitCell, digitCell, Math.max(1, Math.floor(digitCell * 0.18)));
    const scoreWidth = scoreHud.columns * digitCell;
    const x = portrait ? -scoreWidth / 2 : boardX + boardWidth + 48;
    const y = portrait ? boardY + boardHeight + Math.max(18, digitCell * 2) : boardY + boardHeight - scoreHud.rows * digitCell;
    setTilemapTransform(api.read && api.read.find("2048 Score"), x, y);
  }
  if (bestHud) {
    layoutTilemap(bestHud, digitCell, digitCell, Math.max(1, Math.floor(digitCell * 0.18)));
    const bestWidth = bestHud.columns * digitCell;
    const x = portrait ? -bestWidth / 2 : boardX + boardWidth + 48;
    const y = portrait ? boardY + boardHeight + Math.max(58, digitCell * 8) : boardY + boardHeight - bestHud.rows * digitCell - Math.max(42, digitCell * 7);
    setTilemapTransform(api.read && api.read.find("2048 Best"), x, y);
  }

  const tileInset = Math.max(4, Math.floor(cell * 0.08));
  const tileFont = Math.max(14, Math.floor(cell * 0.36));
  state.layout = { boardX: boardX, boardY: boardY, cell: cell, tileInset: tileInset, tileSize: cell - tileInset * 2, rows: rows };
  layoutTiles();
  const panelWidth = portrait ? Math.min(width - 36, boardWidth) : Math.min(220, Math.max(160, width * 0.18));
  const panelHeight = Math.max(26, Math.floor(cell * 0.42));
  const panelFont = Math.max(13, Math.floor(cell * 0.22));
  setTextBox(scoreTextEntity, portrait ? -panelWidth / 2 : boardX + boardWidth + 42, portrait ? boardY + boardHeight + 18 : boardY + boardHeight - panelHeight, panelWidth, panelHeight, panelFont, "#f9f6f2");
  setTextBox(bestTextEntity, portrait ? -panelWidth / 2 : boardX + boardWidth + 42, portrait ? boardY + boardHeight + 18 + panelHeight + 8 : boardY + boardHeight - panelHeight * 2 - 12, panelWidth, panelHeight, panelFont, "#f9f6f2");
  setTextBox(statusTextEntity, portrait ? -panelWidth / 2 : boardX + boardWidth + 42, portrait ? boardY - panelHeight - 16 : boardY + 10, panelWidth, panelHeight, panelFont, state.phase === "playing" ? "#776e65" : state.phase === "won" ? "#edc22e" : "#f65e3b");

  if (statusHud) {
    const statusCell = Math.max(12, Math.floor(cell * 0.22));
    layoutTilemap(statusHud, statusCell, statusCell, Math.max(1, Math.floor(statusCell * 0.14)));
    const statusWidth = statusHud.columns * statusCell;
    const x = portrait ? -statusWidth / 2 : boardX + boardWidth + 48;
    const y = portrait ? boardY - Math.max(42, statusCell * 3) : boardY + Math.max(14, statusCell);
    setTilemapTransform(api.read && api.read.find("2048 Status"), x, y);
  }
}

function drawNumberHud(tilemap, value) {
  if (!tilemap) return;
  tilemap.clear(0);
  const text = String(Math.min(999999, Math.max(0, Math.floor(value || 0)))).padStart(6, "0");
  for (let i = 0; i < text.length; i++) {
    const pattern = digits[text[i]] || digits[0];
    const ox = i * 4;
    for (let y = 0; y < pattern.length; y++) {
      for (let x = 0; x < pattern[y].length; x++) {
        if (pattern[y][x] === "1") tilemap.setCell(ox + x, tilemap.rows - 1 - y, 1);
      }
    }
  }
}

function drawStatus() {
  if (!statusHud) return;
  const value = state.phase === "playing" ? 1 : state.phase === "won" ? 2 : 3;
  statusHud.clear(value);
}

function layoutTiles() {
  const layout = state.layout;
  if (!layout) return;
  let transitions = state.transitions || [];
  let slot = 0;
  const moveDuration = Number(config.tileMoveDuration || 150);
  const spawnDuration = Number(config.tileSpawnDuration || 110);
  const token = state.animationToken || 0;
  const shouldTween = state.lastTweenToken !== token;
  if (transitions.length && state.transitionTimerToken !== token) {
    state.transitionTimerToken = token;
    state.transitionStartedAt = performance.now();
  }
  if (transitions.length && performance.now() - (state.transitionStartedAt || 0) > Math.max(moveDuration, spawnDuration) + 40) {
    state.transitions = [];
    transitions = [];
  }
  const active = transitions.length ? transitions : [];

  if (active.length) {
    for (const transition of active) {
      if (slot >= tileVisualEntities.length) break;
      const from = cellPosition(transition.fromX, transition.fromY);
      const to = cellPosition(transition.toX, transition.toY);
      const value = transition.value;
      setVisualTile(slot, value, to.x, to.y, layout.tileSize);
      setTextBox(tileTextEntities[slot], to.x, to.y, layout.tileSize, layout.tileSize, Math.max(14, Math.floor(layout.cell * 0.36)), value <= 4 ? "#776e65" : "#f9f6f2");
      setStableText(tileTextEntities[slot], "2048 Tile " + slot, value ? String(value) : "");
      if (shouldTween) {
        const scaleFrom = transition.spawn ? 0.2 : 1;
        const duration = transition.spawn ? spawnDuration : moveDuration;
        addTween(tileVisualEntities[slot], from, to, duration, scaleFrom, 1);
        addTween(tileTextEntities[slot], from, to, duration, scaleFrom, 1);
      }
      slot++;
    }
  } else {
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const value = state.grid[y][x];
        if (!value || slot >= tileVisualEntities.length) continue;
        const position = cellPosition(x, y);
        setVisualTile(slot, value, position.x, position.y, layout.tileSize);
        setTextBox(tileTextEntities[slot], position.x, position.y, layout.tileSize, layout.tileSize, Math.max(14, Math.floor(layout.cell * 0.36)), value <= 4 ? "#776e65" : "#f9f6f2");
        setStableText(tileTextEntities[slot], "2048 Tile " + slot, String(value));
        slot++;
      }
    }
  }

  for (; slot < tileVisualEntities.length; slot++) {
    setVisualTile(slot, 0, 0, 0, layout.tileSize);
    setStableText(tileTextEntities[slot], "2048 Tile " + slot, "");
  }
  if (shouldTween) state.lastTweenToken = token;
}

function drawText() {
  setStableText(scoreTextEntity, "2048 Score Text", "SCORE " + state.score);
  setStableText(bestTextEntity, "2048 Best Text", "BEST " + state.best);
  setStableText(statusTextEntity, "2048 Status Text", state.phase === "playing" ? "Swipe / Arrow Keys" : state.phase === "won" ? "2048! Press R" : "Game Over - Press R");
}

function drawBoard() {
  updateLayout();
  board.clear(emptyIndex);
  drawNumberHud(scoreHud, state.score);
  drawNumberHud(bestHud, state.best);
  drawStatus();
  drawText();
}

function installPointerInput() {
  if (state.pointerReady) return;
  const canvas = document.getElementById("player-canvas");
  if (!canvas || !canvas.addEventListener) return;
  state.pointerReady = true;
  api.debug.addDisposer(function () {
    state.pointerReady = false;
    state.pointerCanvas = null;
    state.pointerStart = null;
  });
  state.pointerStart = null;
  api.debug.listen(canvas, "pointerdown", function (event) {
    state.pointerStart = { x: event.clientX, y: event.clientY };
  });
  api.debug.listen(canvas, "pointerup", function (event) {
    if (!state.pointerStart) return;
    const dx = event.clientX - state.pointerStart.x;
    const dy = event.clientY - state.pointerStart.y;
    state.pointerStart = null;
    const threshold = Number(config.swipeThreshold || 24);
    if (Math.max(Math.abs(dx), Math.abs(dy)) < threshold) return;
    state.pendingDirection = Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? "left" : "right") : (dy < 0 ? "up" : "down");
  });
}

if (!state.ready) {
  reset();
  state.ready = true;
  api.debug.console.log("2048 Starter Kit ready.");
}
installPointerInput();

if (api.input.wasPressed("Restart") || api.input.wasPressed("KeyR")) reset();
let direction = null;
if (api.input.wasPressed("MoveLeft") || api.input.wasPressed("ArrowLeft") || api.input.wasPressed("KeyA")) direction = "left";
else if (api.input.wasPressed("MoveRight") || api.input.wasPressed("ArrowRight") || api.input.wasPressed("KeyD")) direction = "right";
else if (api.input.wasPressed("MoveUp") || api.input.wasPressed("ArrowUp") || api.input.wasPressed("KeyW")) direction = "up";
else if (api.input.wasPressed("MoveDown") || api.input.wasPressed("ArrowDown") || api.input.wasPressed("KeyS")) direction = "down";
if (!direction && state.pendingDirection) {
  direction = state.pendingDirection;
  state.pendingDirection = null;
}
if (direction) {
  if (state.phase === "won" && config.continueAfterWin) state.phase = "playing";
  move(direction);
}

drawBoard();
